import math

def transmissibility(r, zeta):
    return math.sqrt(1 + (2 * zeta * r) ** 2) / math.sqrt((1 - r**2) ** 2 + (2 * zeta * r) ** 2)

def isolator_stiffness(m, f_forcing, tr_max, zeta=0.0):
    """Largest total mount stiffness (N/m) for which a machine of mass m (kg), shaking at
    f_forcing (Hz), passes at most the fraction tr_max (less than 1) of its force to the floor."""
    r = math.sqrt(2)                            # only the start of isolation: not enough
    fn = f_forcing / r
    return m * (2 * math.pi * fn) ** 2

