import math

def transmissibility(r, zeta):
    return math.sqrt(1 + (2 * zeta * r) ** 2) / math.sqrt((1 - r**2) ** 2 + (2 * zeta * r) ** 2)

def isolator_stiffness(m, f_forcing, tr_max, zeta=0.0):
    lo, hi = math.sqrt(2), 1000.0               # TR falls steadily as r grows beyond sqrt(2)
    for _ in range(200):                        # bisection for TR(r) = tr_max
        mid = (lo + hi) / 2
        if transmissibility(mid, zeta) > tr_max:
            lo = mid
        else:
            hi = mid
    fn = f_forcing / hi                         # the highest natural frequency allowed
    return m * (2 * math.pi * fn) ** 2
